// pseudo: tenant-aware JWKS fetch with cache
async function getTenantKeys(tenant) {
  const cached = cache.get(tenant);
  if (cached) return cached;
  const keys = await fetch(tenant.jwks_uri).then(r => r.json());
  cache.set(tenant, keys, 30000); // 30s
  return keys;
}
